//! Gallery, as Windows 11 File Explorer has it: a navigation pane node
//! named "Gallery" ([build 23435]) right under Home, opening the photos of
//! the Pictures folder and its subfolders as thumbnails, the most recently
//! taken at the top ([KB, September 26, 2023]), in month groups.
//!
//! Every picture here is generated by the test (flat colours, no people)
//! and every folder name is fictional.
//!
//! [build 23435]: https://blogs.windows.com/windows-insider/2023/04/14/announcing-windows-11-insider-preview-build-23435/
//! [KB, September 26, 2023]: https://support.microsoft.com/en-us/topic/september-26-2023-windows-configuration-update-542780c2-594c-46cb-979d-11116fe164ba

use std::fs;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use gtk::glib;
use gtk::prelude::*;
use ox_core::location::file_uri;
use ox_core::places::FolderLocations;

use crate::test_support::harness::{wait_for, wait_until, TestWindow};
use crate::test_support::pictures::{jpeg_bytes, png_bytes};

/// Gallery's address.
pub(super) const GALLERY: &str = "ox:gallery";

/// A home with a Pictures folder, whose standard folders the window
/// uses instead of the test machine's.
pub(super) struct PicturesHome {
    _root: tempfile::TempDir,
    pub(super) home: PathBuf,
    config: PathBuf,
}

impl PicturesHome {
    /// A home whose Pictures folder exists and is empty.
    pub(super) fn new() -> Self {
        let home = Self::without_pictures();
        fs::create_dir_all(home.pictures()).expect("a Pictures folder");
        home
    }

    /// A home with no Pictures folder at all.
    pub(super) fn without_pictures() -> Self {
        let root = tempfile::tempdir().expect("the test home has room");
        let base = fs::canonicalize(root.path()).expect("the folder resolves");
        let home = base.join("home");
        let config = base.join("config");
        fs::create_dir_all(&home).expect("a home");
        fs::create_dir_all(&config).expect("a config folder");
        Self {
            _root: root,
            home,
            config,
        }
    }

    pub(super) fn pictures(&self) -> PathBuf {
        self.home.join("Pictures")
    }

    pub(super) fn locations(&self) -> FolderLocations {
        FolderLocations::new(self.home.clone(), &self.config)
    }
}

/// Writes a JPEG taken at `taken` (EXIF text) to `path`.
pub(super) fn write_taken(path: &Path, taken: &str) {
    write_file(path, &jpeg_bytes(0x0033_6699, Some(taken)));
}

/// Writes a PNG without EXIF to `path`, modified at the local `date`
/// (`YYYY-MM-DD`, noon).
pub(super) fn write_modified(path: &Path, date: &str) {
    write_file(path, &png_bytes(0x0099_6633));
    set_modified(path, date);
}

fn write_file(path: &Path, bytes: &[u8]) {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).expect("the folder");
    }
    fs::write(path, bytes).expect("the picture is written");
}

/// Sets the modification time of `path` to noon of the local `date`
/// (`YYYY-MM-DD`).
pub(super) fn set_modified(path: &Path, date: &str) {
    let mut parts = date.split('-').map(|part| part.parse::<i32>().expect("a number"));
    let (year, month, day) = (
        parts.next().expect("a year"),
        parts.next().expect("a month"),
        parts.next().expect("a day"),
    );
    let local = glib::DateTime::from_local(year, month, day, 12, 0, 0.0).expect("a date");
    let seconds = u64::try_from(local.to_unix()).expect("after 1970");
    fs::File::options()
        .write(true)
        .open(path)
        .and_then(|file| file.set_modified(UNIX_EPOCH + Duration::from_secs(seconds)))
        .expect("the date is set");
}

/// A window on the home folder of `home`, whose standard folders are
/// `home`'s, then on Gallery.
pub(super) fn gallery_window(home: &PicturesHome) -> TestWindow {
    let test = TestWindow::open_with_standard_folders(&file_uri(&home.home), home.locations(), |_| {});
    test.window.navigate(GALLERY).expect("Gallery opens");
    wait_until("Gallery", || {
        test.window.current_uri().as_deref() == Some(GALLERY)
    });
    test.wait_for_listing("Gallery");
    test
}

/// The month groups shown, in order, each with its count.
pub(super) fn month_groups(test: &TestWindow) -> Vec<String> {
    crate::test_support::harness::wait_for_frames(&test.window, 2);
    let Some(layout) = test
        .window
        .folder_pane()
        .grouped()
        .and_then(|grouped| grouped.layout())
    else {
        return Vec::new();
    };
    layout
        .groups()
        .iter()
        .map(|group| format!("{} ({})", group.title, group.len()))
        .collect()
}

/// The heading Gallery gives a month: its full name and year, in the
/// local language.
fn month_title(year: i32, month: i32) -> String {
    glib::DateTime::from_local(year, month, 1, 12, 0, 0.0)
        .and_then(|date| date.format("%B %Y"))
        .expect("a month name")
        .to_string()
}

/// "Gallery" is the navigation pane's row right under Home, with "Show
/// more items in the navigation pane" on and off, and opens Gallery,
/// titled Gallery.
///
/// parity: HOME-017
#[gtk::test]
fn the_gallery_row_is_right_under_home_and_opens_gallery() {
    let home = PicturesHome::new();
    let test = TestWindow::open_with_standard_folders(&file_uri(&home.home), home.locations(), |_| {});
    for more_items in [true, false] {
        test.set_more_navigation_pane_items(more_items);
        wait_until("the Gallery row", || {
            test.window
                .sidebar()
                .labels()
                .iter()
                .any(|label| label == "Gallery")
        });
        let labels = test.window.sidebar().labels();
        assert_eq!(
            &labels[..2],
            ["Home", "Gallery"],
            "more items {more_items}: {labels:?}"
        );
    }
    let row = super::sidebar::row_named(&test, "Gallery");
    row.activate();
    wait_until("Gallery", || {
        test.window.current_uri().as_deref() == Some(GALLERY)
    });
    test.wait_for_listing("Gallery");
    assert_eq!(test.window.title().as_deref(), Some("Gallery — OpenXplorer"));
}

/// Typing "Gallery" in the address bar opens Gallery; Back and Forward
/// step to and from it, and a new tab can show it.
///
/// parity: HOME-018
#[gtk::test]
fn typing_gallery_opens_it_and_back_and_forward_step_through_it() {
    let home = PicturesHome::new();
    write_taken(&home.pictures().join("lake.jpg"), "2025:06:01 09:00:00");
    let test = TestWindow::open_with_standard_folders(&file_uri(&home.home), home.locations(), |_| {});
    for typed in ["Gallery", "  gallery ", GALLERY] {
        test.activate("location", None);
        test.window.submit_address(typed);
        wait_until(typed, || test.window.current_uri().as_deref() == Some(GALLERY));
        test.wait_for_listing("Gallery");
        assert_eq!(test.names(), ["lake.jpg"]);
        test.activate("back", None);
        wait_until("the home folder", || {
            test.window.current_uri() == Some(file_uri(&home.home))
        });
    }
    test.activate("forward", None);
    wait_until("Gallery again", || {
        test.window.current_uri().as_deref() == Some(GALLERY)
    });
    test.window.add_tab(GALLERY).expect("a tab on Gallery");
    wait_until("a second tab on Gallery", || {
        test.window.tab_count() == 2 && test.window.current_uri().as_deref() == Some(GALLERY)
    });
}

/// Photos are grouped by month, newest first, each month newest first:
/// the date taken from EXIF where the photo has one, else the date
/// modified. Photos in subfolders of Pictures are included; other files,
/// folders and, until hidden items are shown, hidden photos are not.
///
/// parity: HOME-019, HOME-020
#[gtk::test]
fn photos_are_grouped_by_month_newest_first_by_date_taken_or_modified() {
    let home = PicturesHome::new();
    let pictures = home.pictures();
    // Taken in December 2024, modified now: grouped by the date taken.
    write_taken(&pictures.join("snow.jpg"), "2024:12:24 10:00:00");
    // Two taken on the same day of March 2026, the later one first.
    write_taken(&pictures.join("Trips/morning.jpg"), "2026:03:14 08:00:00");
    write_taken(&pictures.join("Trips/evening.jpg"), "2026:03:14 19:30:00");
    // No EXIF: the date modified places it.
    write_modified(&pictures.join("Scans/receipt.png"), "2025-07-02");
    write_modified(&pictures.join("Scans/Old/map.png"), "2024-12-01");
    fs::write(pictures.join("notes.txt"), "not a photo").expect("a text file");
    write_taken(&pictures.join(".secret.jpg"), "2026:01:05 12:00:00");

    let test = gallery_window(&home);

    assert_eq!(
        test.names(),
        ["evening.jpg", "morning.jpg", "receipt.png", "snow.jpg", "map.png"]
    );
    assert_eq!(
        month_groups(&test),
        [
            format!("{} (2)", month_title(2026, 3)),
            format!("{} (1)", month_title(2025, 7)),
            format!("{} (2)", month_title(2024, 12)),
        ]
    );

    test.activate("hidden", None);
    wait_until("the hidden photo", || {
        test.names().contains(&".secret.jpg".to_owned())
    });
    assert_eq!(month_groups(&test)[1], format!("{} (1)", month_title(2026, 1)));
}

/// A photo saved into Pictures, or one of its subfolders, while Gallery
/// is open appears in its month; a deleted one disappears.
///
/// parity: HOME-021
#[gtk::test]
fn photos_added_or_removed_while_gallery_is_open_follow_at_once() {
    let home = PicturesHome::new();
    let pictures = home.pictures();
    write_taken(&pictures.join("Birds/heron.jpg"), "2025:05:10 07:00:00");
    let test = gallery_window(&home);
    assert_eq!(test.names(), ["heron.jpg"]);

    write_taken(&pictures.join("Birds/swan.jpg"), "2025:05:20 07:00:00");
    write_taken(&pictures.join("owl.jpg"), "2023:02:02 22:00:00");
    wait_until("the new photos", || test.names().len() == 3);
    assert_eq!(test.names(), ["swan.jpg", "heron.jpg", "owl.jpg"]);
    assert_eq!(
        month_groups(&test),
        [
            format!("{} (2)", month_title(2025, 5)),
            format!("{} (1)", month_title(2023, 2)),
        ]
    );

    fs::remove_file(pictures.join("Birds/heron.jpg")).expect("the photo is removed");
    wait_until("the removed photo to go", || {
        test.names() == ["swan.jpg", "owl.jpg"]
    });
}

/// Enter opens the selected photo in its default application, and Open
/// file location opens its folder with the photo selected.
///
/// parity: HOME-022
#[gtk::test]
fn a_photo_opens_in_its_application_and_its_location_opens_with_it_selected() {
    let home = PicturesHome::new();
    write_taken(&home.pictures().join("Garden/tulip.jpg"), "2025:04:01 10:00:00");
    let test = gallery_window(&home);
    test.window.select_named("tulip.jpg");

    test.activate("open", None);
    let tulip = file_uri(&home.pictures().join("Garden/tulip.jpg"));
    wait_until("the photo to open", || {
        test.context
            .recorded_launches()
            .iter()
            .any(|launch| launch.contains(&tulip))
    });

    test.activate("open-file-location", None);
    let garden = file_uri(&home.pictures().join("Garden"));
    wait_until("the photo's folder", || {
        test.window.current_uri() == Some(garden.clone())
    });
    test.wait_for_listing("Garden");
    wait_until("the photo selected", || test.selected_names() == ["tulip.jpg"]);
}

/// Gallery shows nothing, and no error, while Pictures is empty or does
/// not exist; it says there are no photos.
///
/// parity: HOME-023
#[gtk::test]
fn an_empty_or_missing_pictures_folder_leaves_gallery_empty_without_an_error() {
    for home in [PicturesHome::new(), PicturesHome::without_pictures()] {
        let test = gallery_window(&home);
        assert!(test.names().is_empty());
        assert_eq!(test.window.shown_message().as_str(), "");
        crate::test_support::harness::wait_for_frames(&test.window, 2);
        let shown: Vec<String> = crate::test_support::harness::descendants::<gtk::Label>(&test.window)
            .into_iter()
            .filter(|label| label.is_mapped())
            .map(|label| label.text().to_string())
            .collect();
        assert!(shown.iter().any(|text| text.contains("No photos")), "{shown:?}");
    }
}

/// A large Pictures folder fills Gallery in batches, the first well
/// before the last, and leaving Gallery stops the listing.
///
/// parity: HOME-024
#[gtk::test]
fn a_large_library_arrives_in_batches_and_leaving_stops_it() {
    let home = PicturesHome::new();
    let bytes = jpeg_bytes(0x0066_9933, Some("2025:01:01 12:00:00"));
    for folder in 0..20 {
        for photo in 0..100 {
            write_file(
                &home.pictures().join(format!("Roll {folder}/frame {photo}.jpg")),
                &bytes,
            );
        }
    }
    let test = TestWindow::open_with_standard_folders(&file_uri(&home.home), home.locations(), |_| {});
    let started = SystemTime::now();
    test.window.navigate(GALLERY).expect("Gallery opens");
    wait_until("the first photos", || !test.names().is_empty());
    let first = started.elapsed().unwrap_or_default();
    assert!(first < Duration::from_secs(5), "the first photos took {first:?}");
    test.wait_for_listing("every photo");
    assert_eq!(test.names().len(), 2000);

    test.window.navigate(GALLERY).expect("Gallery again");
    test.window.navigate(&file_uri(&home.home)).expect("home");
    test.wait_for_listing("the home folder");
    wait_for(Duration::from_millis(300));
    assert!(!test.names().iter().any(|name| name.starts_with("frame")));
}

/// Sets the folders added to Gallery's collection in the settings file,
/// as another window or process would.
fn set_gallery_folders(test: &TestWindow, folders: &[String]) {
    let update = ox_core::settings::PreferencesUpdate::from_json(&serde_json::json!({
        "galleryFolders": folders,
    }))
    .expect("an update");
    ox_core::settings::Settings::open(test.settings_directory())
        .update_preferences(&update)
        .expect("the settings file takes the folders");
    test.context.reload_settings();
}

/// Whether the command bar shows Gallery's Collection menu button.
fn shows_collection(test: &TestWindow) -> bool {
    crate::test_support::harness::descendants::<gtk::MenuButton>(&test.window)
        .iter()
        .any(|button| button.has_css_class("collection-command") && button.is_visible())
}

/// Gallery's Collection menu, shown only in Gallery, lists Pictures and
/// the folders added to the collection; choosing one shows only its
/// photos, and a folder added or removed joins or leaves Gallery
/// ("You can choose which folders are shown in Gallery through the
/// Collection dropdown", build 23435).
///
/// parity: HOME-025
#[gtk::test]
fn the_collection_menu_chooses_folders_and_added_folders_join_gallery() {
    let home = PicturesHome::new();
    write_taken(&home.pictures().join("lighthouse.jpg"), "2025:01:10 10:00:00");
    let camera = home.home.join("Camera imports");
    write_taken(&camera.join("dunes.jpg"), "2025:02:20 10:00:00");
    let camera_uri = file_uri(&camera);
    let test = gallery_window(&home);
    assert_eq!(test.names(), ["lighthouse.jpg"]);
    assert!(shows_collection(&test));

    set_gallery_folders(&test, std::slice::from_ref(&camera_uri));
    wait_until("the added folder's photo", || test.names().len() == 2);
    assert_eq!(test.names(), ["dunes.jpg", "lighthouse.jpg"]);

    test.activate("gallery-collection", Some(&camera_uri));
    wait_until("only the added folder", || test.names() == ["dunes.jpg"]);
    test.activate("gallery-collection", Some("all"));
    wait_until("every folder again", || test.names().len() == 2);

    test.activate("gallery-remove-folder", Some(&camera_uri));
    wait_until("the removed folder to leave", || {
        test.names() == ["lighthouse.jpg"]
    });
    let saved = std::fs::read_to_string(test.settings_directory().join("settings.json")).unwrap_or_default();
    assert!(!saved.contains("Camera imports"), "the folder is no longer saved");

    test.window.navigate(&file_uri(&home.home)).expect("home");
    test.wait_for_listing("the home folder");
    assert!(!shows_collection(&test), "Collection shows only in Gallery");
}
